{
  "name": "STAR Chatterbox 模拟后端",
  "name_en": "STAR Chatterbox Backend",
  "manufacturer": "",
  "description": "这是一个面向 Hamilton STAR 液体处理平台的非实体模拟组件。它通过返回虚拟机器配置、吸头状态、96头固件信息、iSWAP 状态与位置等数据，并模拟通道及 iSWAP 运动，用于开发、调试、命令测试和流程验证，而非直接驱动真实仪器。",
  "description_en": "This is a non-physical simulation component for the Hamilton STAR liquid handling platform. It provides mock machine configuration, tip status, 96-head firmware data, iSWAP status and positions, and simulated channel and iSWAP motion for development, debugging, command testing, and workflow validation rather than direct control of real hardware.",
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化模拟 STAR 后端并检测已启用模块。",
      "description_en": "Initialize the simulated STAR backend and detect enabled modules."
    },
    {
      "action_name": "auto-stop",
      "description": "停止模拟后端。",
      "description_en": "Stop the simulated backend."
    },
    {
      "action_name": "auto-send_raw_command",
      "description": "向模拟 STAR 会话发送原始命令。",
      "description_en": "Send a raw command to the simulated STAR session."
    },
    {
      "action_name": "auto-request_machine_configuration",
      "description": "请求模拟整机配置数据。",
      "description_en": "Request mock machine configuration data."
    },
    {
      "action_name": "auto-request_extended_configuration",
      "description": "请求模拟扩展配置数据。",
      "description_en": "Request mock extended configuration data."
    },
    {
      "action_name": "auto-request_tip_presence",
      "description": "请求各通道的模拟吸头存在状态。",
      "description_en": "Request simulated tip presence status for each channel."
    },
    {
      "action_name": "auto-request_z_pos_channel_n",
      "description": "请求指定通道的模拟 Z 位置。",
      "description_en": "Request the simulated Z position of a specified channel."
    },
    {
      "action_name": "auto-channel_dispensing_drive_request_position",
      "description": "请求指定通道分液驱动的模拟位置。",
      "description_en": "Request the simulated dispensing drive position of a specified channel."
    },
    {
      "action_name": "auto-move_channel_y",
      "description": "模拟移动指定通道的 Y 轴位置。",
      "description_en": "Simulate moving the Y position of a specified channel."
    },
    {
      "action_name": "auto-step_off_foil",
      "description": "模拟通道在封膜上踏离的操作流程。",
      "description_en": "Simulate the step-off-foil operation for channels."
    },
    {
      "action_name": "auto-pierce_foil",
      "description": "模拟使用通道刺穿封膜。",
      "description_en": "Simulate piercing foil with channels."
    },
    {
      "action_name": "auto-head96_request_firmware_version",
      "description": "请求模拟 96 头模块的固件版本。",
      "description_en": "Request the mock firmware version of the 96-head module."
    },
    {
      "action_name": "auto-request_iswap_initialization_status",
      "description": "请求模拟 iSWAP 的初始化状态。",
      "description_en": "Request the simulated initialization status of the iSWAP."
    },
    {
      "action_name": "auto-iswap_parked",
      "description": "获取 iSWAP 是否处于停放位置。",
      "description_en": "get whether the iSWAP is parked"
    },
    {
      "action_name": "auto-move_iswap_x",
      "description": "模拟移动 iSWAP 的 X 轴位置。",
      "description_en": "Simulate moving the iSWAP X position."
    },
    {
      "action_name": "auto-move_iswap_y",
      "description": "模拟移动 iSWAP 的 Y 轴位置。",
      "description_en": "Simulate moving the iSWAP Y position."
    },
    {
      "action_name": "auto-move_iswap_z",
      "description": "模拟移动 iSWAP 的 Z 轴位置。",
      "description_en": "Simulate moving the iSWAP Z position."
    },
    {
      "action_name": "auto-slow_iswap",
      "description": "在上下文中临时将模拟 iSWAP 切换为低速运动。",
      "description_en": "Temporarily switch the simulated iSWAP to slow motion within a context."
    }
  ],
  "tag_hints": [
    "liquid handling simulation",
    "Hamilton STAR",
    "mock backend",
    "iSWAP",
    "96-head",
    "tip presence emulation",
    "foil piercing workflow"
  ]
}

